-- Additional named Egyptian sites and curated alternate search names.
-- Safe to rerun: inserts are skipped by canonical name and aliases are merged.

INSERT INTO "egypt_pois"
  ("name", "lng", "lat", "category", "alternate_names", "description", "history_notes", "info_tips", "fun_activities")
SELECT v."name", v."lng", v."lat", v."category"::"poi_category_enum",
       v."alternate_names"::jsonb, v."description", v."history_notes",
       v."info_tips"::jsonb, v."fun_activities"::jsonb
FROM (
  VALUES
    ('Rosetta National Museum', 30.4168, 31.4044, 'modern human made',
     '["Rashid National Museum","Rosetta Museum","متحف رشيد"]',
     'A museum in Rashid (Rosetta) presenting the town’s history and its role in the discovery of the Rosetta Stone.',
     'Rashid is associated with the 1799 discovery of the Rosetta Stone, whose parallel inscriptions helped scholars decipher Egyptian hieroglyphs.',
     '["Confirm current opening hours and ticket arrangements before visiting.","Rosetta is a working town; follow local guidance around historic buildings and waterfront areas."]',
     '["Visit the museum before exploring Rashid’s historic streets.","Look for the town’s preserved Ottoman-era houses and traditional mills."]'),
    ('Abu Shahin Mill Rashid', 30.4155, 31.4035, 'historic human made',
     '["Abu Shaheen Mill","Abu Shahin Windmill","Rosetta Windmill","طاحونة أبو شاهين"]',
     'A historic wind-powered grain mill in Rashid, illustrating traditional milling technology used in the Nile Delta.',
     'The mill is part of Rashid’s preserved historic townscape, known for Ottoman-period houses and civic buildings.',
     '["Check whether the interior is open to visitors.","Respect residents and ask before photographing private property."]',
     '["Explore the mill with Rashid’s nearby historic houses.","Notice the mill’s wind-catching structure and its relationship to the surrounding streets."]'),
    ('Amasyali House Rashid', 30.4150, 31.4030, 'historic human made',
     '["Amasyali House","Amasyali House Museum","Rosetta Historic House","منزل الأمصيلي"]',
     'A preserved historic merchant house in Rashid, known for its decorated brick facade and traditional domestic layout.',
     'Rashid’s historic houses reflect the town’s prosperity as a Nile and Mediterranean trading center during the Ottoman period.',
     '["Confirm visitor access locally; historic houses may have restricted hours.","Stay within marked visitor areas to help protect fragile interiors."]',
     '["Compare the facade’s brick patterns with nearby Rashid houses.","Explore the historic quarter on foot with a local guide."]'),
    ('Pharaohs Island Citadel', 34.3370, 29.4690, 'historic human made',
     '["Pharaoh''s Island","Salah ad-Din Citadel on Pharaohs Island","Coral Island Citadel","جزيرة فرعون","قلعة صلاح الدين بجزيرة فرعون"]',
     'A medieval fortress on an island in the Gulf of Aqaba, reached by boat from the Taba area.',
     'The island fortress is associated with the Ayyubid ruler Saladin and the medieval defense of routes through the Gulf of Aqaba.',
     '["Boat access and sea conditions vary; arrange transport locally and follow safety guidance.","Bring sun protection and water; shade and facilities on the island are limited."]',
     '["Explore the fortress walls and elevated views over the Gulf of Aqaba.","View the island from the water on the boat crossing."]'),
    ('Monastery of Saint Macarius, Wadi el-Natrun', 30.3540, 30.3560, 'historic human made',
     '["Deir Abu Maqar","Monastery of Saint Macarius the Great","Wadi Natrun Saint Macarius Monastery","Wadi Natrun Monastery of Saint Macarius"]',
     'An active Coptic Orthodox monastery in Wadi el-Natrun, one of Egypt’s historic centers of Christian monastic life.',
     'The monastery was founded in the fourth century and has remained an important monastic community in the Wadi el-Natrun desert.',
     '["This is an active religious community; verify visitor rules and opening times in advance.","Dress modestly and follow photography restrictions and guidance from monastery staff."]',
     '["Learn about the history of Egyptian monasticism through approved visitor areas.","Visit only the monastery sites open to the public."]'),
    ('Monastery of Saint Bishoy, Wadi el-Natrun', 30.3545, 30.3465, 'historic human made',
     '["Deir Anba Bishoi","Monastery of Saint Pishoy","Wadi Natrun Saint Bishoy Monastery","Wadi Natrun Monastery of Saint Bishoy"]',
     'An active Coptic Orthodox monastery in Wadi el-Natrun, named for the fourth-century monk Bishoy.',
     'The monastery is part of Wadi el-Natrun’s long-standing desert monastic tradition and contains historic churches and monastic buildings.',
     '["Confirm access arrangements before travel; the monastery is an active religious site.","Dress modestly and observe local rules for visitors and photography."]',
     '["Explore the visitor-accessible church and historic buildings.","Pair the visit with another monastery only if access is confirmed in advance."]'),
    ('Athribis Archaeological Site, Sohag', 31.6500, 26.3300, 'historic human made',
     '["Athribis Sohag","Athribis Temple","Wadi Hamama Archaeological Site","أثريبس"]',
     'An archaeological area near Sohag containing the remains of temples, quarries, and settlement from multiple periods.',
     'Athribis developed as a religious and settlement center in Upper Egypt; surviving monuments include Ptolemaic and Roman-period remains.',
     '["Check current site access and local transport before setting out.","The site is exposed; bring water and sun protection and remain on established paths."]',
     '["Look for the temple remains and rock-cut features in the surrounding landscape.","Use a local guide or site interpretation to distinguish the archaeological periods."]'),
    ('Hawara Pyramid', 30.9000, 29.2700, 'historic human made',
     '["Pyramid of Amenemhat III at Hawara","Hawara Pyramid of Amenemhat III","Hawara Labyrinth Site"]',
     'A Middle Kingdom pyramid near Fayoum built for the Twelfth Dynasty king Amenemhat III.',
     'Amenemhat III’s pyramid at Hawara was associated in classical accounts with a large mortuary complex often called the Labyrinth.',
     '["Access can be limited and site conditions change; confirm arrangements locally.","The desert site has little shade, so carry water and sun protection."]',
     '["View the pyramid and surrounding archaeological landscape.","Combine the visit with nearby Fayoum sites only after checking road and access conditions."]'),
    ('Pyramid of Senusret II at el-Lahun', 30.9700, 29.2450, 'historic human made',
     '["Lahun Pyramid","Pyramid of Senusret II","El-Lahun Pyramid"]',
     'A Middle Kingdom pyramid near the village of el-Lahun, built for the Twelfth Dynasty king Senusret II.',
     'The pyramid is part of a wider archaeological landscape that includes the planned settlement commonly known as Kahun or Lahun.',
     '["Confirm access and local transport before visiting.","Stay on established routes around the archaeological remains."]',
     '["Compare the pyramid with nearby Middle Kingdom settlement remains.","Use the landscape to understand how royal monuments related to surrounding communities."]'),
    ('Gebel el-Silsila Quarry', 32.9200, 24.6400, 'historic human made',
     '["Gebel el-Silsileh","Gebel el-Silsila Sandstone Quarries","Silsila Quarry"]',
     'A sandstone quarry landscape along the Nile between Edfu and Kom Ombo, with ancient extraction areas and rock-cut monuments.',
     'Sandstone from Gebel el-Silsila was widely used in temples across Egypt, especially during the New Kingdom.',
     '["Check current access and transport conditions; some areas may require a local boat or guide.","Avoid touching or climbing on carved surfaces."]',
     '["Observe the ancient quarry faces and carved shrines from permitted paths.","Look for traces of how sandstone blocks were cut and moved."]'),
    ('Kom el-Dikka Archaeological Site, Alexandria', 29.8975, 31.1975, 'historic human made',
     '["Kom el-Dikka","Kom el-Dikka Roman Theatre","Roman Amphitheatre of Alexandria","كوم الدكة"]',
     'An archaeological complex in central Alexandria with a Roman-era theatre, lecture halls, baths, and residential remains.',
     'The site preserves remains of ancient Alexandria from the Roman and Byzantine periods, including spaces associated with public performance and education.',
     '["Check current ticketing and opening hours before visiting.","Wear comfortable shoes; the archaeological surfaces are uneven."]',
     '["Explore the theatre and the remains of the ancient lecture halls.","Compare the site’s Roman-era layers with other nearby Alexandria museums."]'),
    ('Rommel Cave Museum, Matrouh', 27.2210, 31.3370, 'modern human made',
     '["Rommel''s Cave Museum","Rommel Cave","Matrouh Rommel Museum","متحف كهف رومل"]',
     'A small museum in a natural cave near Marsa Matruh, associated with the Second World War history of the western desert.',
     'The cave is linked to German Field Marshal Erwin Rommel’s North African campaign during the Second World War.',
     '["Verify opening status and access locally before travel.","Respect the museum displays and any restrictions on photography."]',
     '["View the cave setting and its military-history exhibits.","Combine the visit with a locally guided tour of Marsa Matruh’s wartime sites."]'),
    ('Cleopatra Bath, Marsa Matruh', 27.2500, 31.3500, 'natural',
     '["Cleopatra''s Bath","Cleopatra''s Beach","Marsa Matruh Cleopatra Spring"]',
     'A natural rock pool on the Mediterranean coast near Marsa Matruh, where seawater circulates through openings in the surrounding rocks.',
     'The site is popularly associated with Cleopatra, though the name reflects local tradition rather than established evidence of her historical use.',
     '["Sea conditions can be hazardous; follow local safety advice and posted warnings.","Use designated access routes and avoid climbing on wet rocks."]',
     '["View the coastal rock formations and natural seawater pool.","Visit nearby beaches while following lifeguard and sea-condition guidance."]'),
    ('Mons Claudianus Quarry', 33.2500, 26.8500, 'historic human made',
     '["Mons Claudianus","Roman Mons Claudianus Quarry","Roman Imperial Porphyry Quarry"]',
     'A remote Roman-era quarry settlement in Egypt’s Eastern Desert, developed to extract hard stone for imperial building projects.',
     'The quarry was operated during the Roman period and included work areas, settlement remains, and transport infrastructure.',
     '["This remote desert site requires careful planning and suitable transport; check permits and access before travel.","Do not remove stone or artifacts; bring water, communications, and experienced local support."]',
     '["Explore only with an authorized guide and appropriate desert transport.","Observe the quarry landscape and settlement remains without disturbing them."]'),
    ('Mons Porphyrites Quarry', 33.3700, 27.1500, 'historic human made',
     '["Mons Porphyrites","Roman Porphyry Quarries","Porphyrites Mountain"]',
     'A Roman quarry landscape in the Eastern Desert historically associated with the extraction of imperial porphyry.',
     'Porphyry from this desert quarry was valued in Roman imperial architecture; quarrying required organized routes through a remote landscape.',
     '["The site is remote and may require permits, a specialist guide, and off-road transport.","Plan for desert conditions and do not enter unstable or restricted workings."]',
     '["Visit only as part of a properly planned, authorized desert trip.","Observe quarry features and ancient transport routes from safe ground."]'),
    ('El Arish Castle', 33.8000, 31.1300, 'historic human made',
     '["Arish Castle","El-Arish Fortress","Qal''at al-Arish","قلعة العريش"]',
     'A historic fortress site in El Arish, a coastal city on the northern Sinai Peninsula.',
     'The fortress reflects El Arish’s strategic position on routes connecting Egypt and the eastern Mediterranean; surviving fabric and access conditions may vary.',
     '["Check current security, access, and travel guidance before visiting northern Sinai.","Do not enter closed or restricted areas."]',
     '["Learn about El Arish’s role on historic coastal routes.","View the site only from publicly accessible areas."]'),
    ('Malkata Palace Site, Luxor', 32.5800, 25.6900, 'historic human made',
     '["Malkata","Malqata Palace","Amenhotep III Palace City","ملقطة"]',
     'The remains of a royal palace and settlement complex on Luxor’s West Bank, built during the reign of Amenhotep III.',
     'Malkata served as a royal residence during the New Kingdom and was connected with the king’s jubilee celebrations.',
     '["Check current access and transport conditions for the West Bank site.","The remains are spread across an exposed area; bring water and sun protection."]',
     '["Explore the palace-city landscape with a knowledgeable guide.","Compare the site with other New Kingdom monuments on Luxor’s West Bank."]'),
    ('Deir el-Shelwit Temple, Luxor', 32.6020, 25.6470, 'historic human made',
     '["Deir el-Shelwit","Temple of Isis at Deir el-Shelwit","Deir el-Shelwit Isis Temple","دير الشلويط"]',
     'A small temple on Luxor’s West Bank dedicated to Isis, with surviving decoration from the Roman period.',
     'The temple’s inscriptions and decoration document the continued use of Egyptian religious traditions under Roman rule.',
     '["Verify opening hours and transport locally; the site is away from Luxor’s main visitor cluster.","Follow site rules and avoid touching decorated surfaces."]',
     '["Study the temple reliefs and inscriptions from permitted visitor areas.","Pair the visit with nearby West Bank sites if transport is arranged."]'),
    ('Medamud Temple, Luxor', 32.7100, 25.7400, 'historic human made',
     '["Medamud","Temple of Montu at Medamud","Madu","معبد المدامود"]',
     'An archaeological site north-east of Luxor associated with the ancient cult of Montu.',
     'The temple area was rebuilt and expanded during several periods, including the Middle Kingdom and the Ptolemaic era.',
     '["Confirm access and current site conditions before travelling.","Bring water and sun protection; visitor facilities may be limited."]',
     '["Explore the surviving temple remains with local interpretation.","Compare the site with other Montu temples in the Theban region."]'),
    ('Tod Temple, Luxor Governorate', 32.5400, 25.5700, 'historic human made',
     '["Tod","Tôd Temple","Temple of Montu at Tod","معبد الطود"]',
     'The remains of an ancient temple at Tod, south of Luxor, dedicated to the falcon god Montu.',
     'The temple’s history spans the Middle Kingdom and later periods; a cache of silver objects discovered there is now held in museum collections.',
     '["Check access and transport before visiting this less-visited site.","Respect excavation areas and do not disturb archaeological material."]',
     '["View the temple remains and their setting in the Nile Valley.","Ask a local guide about the site’s Middle Kingdom history and later rebuilding."]'),
    ('Precinct of Mut, Karnak', 32.6550, 25.7160, 'historic human made',
     '["Mut Temple Precinct","Temple of Mut at Karnak","Isheru of Mut","معبد موت"]',
     'A temple precinct south of the main Karnak complex, dedicated to the goddess Mut and centered on a sacred lake.',
     'The precinct formed part of the Theban religious landscape and was connected with the worship of Amun and the royal cult.',
     '["Confirm whether the precinct is open independently or as part of a wider site ticket.","Stay on visitor paths and protect fragile reliefs and sculpture."]',
     '["Explore the temple courts and sacred lake when access is permitted.","Use a guide to understand the precinct’s relationship to Karnak’s main temples."]'),
    ('Kiosk of Qertassi', 32.8770, 23.9550, 'historic human made',
     '["Qertassi Kiosk","Kiosk of Qirtas","Trajan''s Kiosk at Qertassi","كشك قرطاسي"]',
     'A small Roman-period monument near the Kalabsha temple area, relocated during the Nubian monuments rescue campaign.',
     'The kiosk was moved to higher ground during the construction of the Aswan High Dam and the international campaign to save Nubian monuments.',
     '["Check access arrangements with the Kalabsha site operator.","Do not climb on columns or touch carved surfaces."]',
     '["Observe the column capitals and reliefs from permitted visitor areas.","Combine the visit with the nearby Kalabsha monuments."]'),
    ('Temple of Kalabsha, Aswan', 32.8770, 23.9580, 'historic human made',
     '["Kalabsha Temple","Temple of Mandulis at Kalabsha","Talmis Temple","معبد كلابشة"]',
     'A large Nubian temple dedicated to Mandulis, relocated to an island near the Aswan High Dam to protect it from Lake Nasser.',
     'The temple was built and decorated during the Roman period and was moved in the twentieth century as part of the international Nubian monuments rescue campaign.',
     '["Confirm boat access, opening times, and tickets before visiting.","Bring water and sun protection; island shade is limited."]',
     '["Explore the temple’s courts and reliefs from marked visitor paths.","View the monument’s island setting and the surrounding reservoir landscape."]'),
    ('Beni Hassan Tombs, Minya', 31.0900, 27.9300, 'historic human made',
     '["Beni Hasan Tombs","Tombs of Beni Hassan","مقابر بني حسن"]',
     'A group of Middle Kingdom tombs cut into the cliffs near Minya, famous for their intimate scenes of daily life and craftwork.',
     'Beni Hassan was a major administrative and burial site in Middle Egypt. Its tombs preserve painted scenes showing artisans, caravans, and the rhythms of provincial life.',
     '["Check current access and local site conditions before visiting; roads and visitor facilities can change.","Bring water and sun protection because the site is exposed and remote."]',
     '["Look for the painted scenes in the cliff tombs and compare them with other Middle Kingdom burial sites.","Visit with a guide to understand the regional importance of the site within the Nile Valley."]'),
    ('Wadi el-Rayan Protected Area', 30.4000, 29.3300, 'natural',
     '["Wadi Rayan","Rayan Valley","وادي الريان"]',
     'A desert depression and protected wetland area in the Fayoum region, known for lakes, sand dunes, and dramatic desert scenery.',
     'Wadi el-Rayan was shaped by geologic processes and later developed as a protected ecological area in the modern era, becoming an important stop for desert and wetland biodiversity.',
     '["Follow local guidance for safe access around the lake margins and sand paths.","Carry enough water and check weather and route conditions before travelling into the desert."]',
     '["Take in the contrast between turquoise water and the surrounding pale desert landscape.","Pause at a viewpoint to watch how the protected wetlands support birds and desert wildlife."]'),
    ('White Desert National Park, Farafra', 27.3550, 27.2000, 'natural',
     '["Farafra White Desert","White Desert of Farafra","الصحرا البيضاء"]',
     'A dramatic desert landscape of chalk rock formations and wind-carved ridges in the western desert.',
     'The White Desert’s strange formations were sculpted by wind and erosion over long periods, creating one of Egypt’s most distinctive natural landscapes.',
     '["Plan an organized desert trip; roads and seasonal conditions can be severe.","Bring plenty of water, sun protection, and a guide for remote areas."]',
     '["Photograph the surreal rock formations at sunrise or sunset for the best light.","Explore carefully on marked routes and respect the fragility of the desert environment."]'),
    ('Black Desert, Bahariya Oasis', 28.8600, 28.3500, 'natural',
     '["Bahariya Black Desert","Black Desert Bahariya","الصحراء السوداء"]',
     'A basalt-covered desert landscape near Bahariya Oasis, with dark volcanic rock formations and open views across the western desert.',
     'The ridge-like black stone formations are part of the region’s volcanic and desert geology, creating a striking contrast with the oasis and surrounding white desert landscapes.',
     '["Organize transport and desert supplies before visiting remote desert tracks.","Stay with a planned route and avoid wandering away from marked paths."]',
     '["Watch the contrast between black rock and golden desert light at sunset.","Combine the visit with Bahariya Oasis for a full desert-and-oasis day trip."]'),
    ('The Catacombs of Kom el-Shoqafa, Alexandria', 29.9040, 31.1850, 'historic human made',
     '["Kom el-Shoqafa Catacombs","Catacombs of Alexandria","مقابر كوم الشقافة"]',
     'A multi-level Roman-era tomb complex in Alexandria with catacombs, passages, and funerary chambers cut into rock.',
     'Kom el-Shoqafa reflects the mixed cultural traditions of Roman Alexandria, combining Egyptian, Greek, and Roman funerary practices in one burial complex.',
     '["Confirm opening times before you go; ticketing and tours may change.","Wear sturdy shoes; the underground passages are uneven and dimly lit."]',
     '["Explore the chamber layout and funerary carvings to understand the layered cultures of Alexandria.","Compare the site’s architecture with other Roman-era tombs in the Mediterranean world."]'),
    ('Bibliotheca Alexandrina, Alexandria', 29.9090, 31.2080, 'modern human made',
     '["Library of Alexandria","Alexandria Library","مكتبة الإسكندرية"]',
     'A modern cultural and intellectual center in Alexandria designed to echo the legacy of the ancient Library of Alexandria.',
     'The building was inaugurated in the early twenty-first century to revive Alexandria’s historical role as a center of learning, scholarship, and public culture.',
     '["Check the event calendar and exhibition schedules before visiting.","The waterfront setting is ideal for a walk, but plan for weather and transport around the seafront."]',
     '["Browse its exhibitions and reading rooms to understand Alexandria’s wider cultural identity.","Pair the visit with a seafront walk to connect the modern library with the city’s maritime setting."]'),
    ('Marsa Alam Abu Dabab Beach', 34.7800, 24.3000, 'natural',
     '["Abu Dabab Beach","Abu Dabab Bay","شاطئ أبو داباب"]',
     'A Red Sea beach near Marsa Alam, known for clear turquoise water, coral reef access, and sea turtle sightings.',
     'The area is popular for snorkeling and reef visits, with a marine environment that supports fish life and occasional sea turtle activity along the coast.',
     '["Check local sea conditions, tide times, and reef access before swimming.","Use organized snorkeling or dive guidance if you plan to enter the water away from marked areas."]',
     '["Swim or snorkel in the shallow reef zone and look for marine life at the surface.","Take a sunset walk along the beach to see the Red Sea at its calmest."]'),
    ('Temple of Horemheb, Saqqara', 31.2000, 29.8600, 'historic human made',
     '["Horemheb Temple Saqqara","Temple of Horemheb","معبد حورمحب بسقارة"]',
     'An unfinished or partially preserved temple near Saqqara associated with the late Eighteenth Dynasty ruler Horemheb.',
     'The site reflects the late royal building programs of the New Kingdom and its position near the sacred landscape of Saqqara.',
     '["Check current access and site conditions before you travel.","Stay on marked paths and avoid fragile remains or restoration areas."]',
     '["Compare the remains with the larger monuments of Saqqara and the surrounding necropolis.","Use a guide to understand the temple’s place in the late Eighteenth Dynasty context."]'),
    ('Ain Umm Dabadib, Siwa', 25.4300, 29.2000, 'natural',
     '["Umm Dabadib Spring","Ain Dabadib","عين أم دبدب"]',
     'A desert spring feeding a small oasis area in the Siwa region, valued for water and shade in a dry landscape.',
     'Siwa’s springs are essential to the oasis economy and to local heritage, linking settlement, agriculture, and travel routes in the western desert.',
     '["Ask for local guidance before visiting remote springs and protected desert routes.","Carry water and plan for heat, even when the spring area feels shaded and calm."]',
     '["See how water supports life in the dry desert environment.","Combine the visit with other Siwa oasis stops and local heritage sites."]'),
    ('Kaitbay Gardens, Alexandria', 29.9040, 31.2020, 'modern human made',
     '["Qaitbay Gardens","Qaitbay Court Gardens","حدائق قايتباي"]',
     'A waterfront garden area near the Citadel of Qaitbay, preserving the sea-facing setting of Alexandria’s historic fortification.',
     'The gardens provide a modern public landscape around one of Alexandria’s most recognizable defensive monuments, tying the city’s heritage to its coastal public spaces.',
     '["Visit in the cooler hours for a comfortable walk near the sea.","Watch for local events and arranged public gatherings along the waterfront promenade."]',
     '["Enjoy the sea breeze while taking in the citadel and harbor setting.","Use the gardens as a rest stop before exploring nearby historic Alexandria sites."]'),
    ('Ain Khadra Springs, Sinai', 33.6500, 29.2500, 'natural',
     '["Ain Khadra","Khadra Springs","عين خضرة"]',
     'A spring-fed natural water source in the Sinai highlands, valued for relief from the desert climate and as a stop on local travel routes.',
     'The spring reflects the importance of groundwater resources in Sinai, where desert travelers and communities have long relied on accessible water points.',
     '["Check local conditions and route safety before travelling to remote water sources.","Respect the environment and avoid overusing delicate water sites."]',
     '["Pause at the spring to understand how water shapes life in the Sinai landscape.","Combine the stop with nearby trails or mountain viewpoints where conditions allow."]')
) AS v("name", "lng", "lat", "category", "alternate_names", "description", "history_notes", "info_tips", "fun_activities")
WHERE NOT EXISTS (
  SELECT 1 FROM "egypt_pois" p WHERE lower(p."name") = lower(v."name")
);

UPDATE "egypt_pois" AS p
SET "alternate_names" = (
  SELECT jsonb_agg(DISTINCT alias)
  FROM jsonb_array_elements_text(
    COALESCE(p."alternate_names", '[]'::jsonb) || v."alternate_names"::jsonb
  ) AS aliases(alias)
)
FROM (
  VALUES
    ('Great Pyramid of Giza (Khufu)',     '["Great Pyramid","Pyramid of Khufu","Pyramid of Cheops","Cheops Pyramid","الهرم الأكبر","هرم خوفو"]'),
    ('Pyramid of Khafre', '["Pyramid of Chephren","Khafre Pyramid","هرم خفرع"]'),
    ('Pyramid of Menkaure', '["Pyramid of Mykerinos","Menkaure Pyramid","هرم منقرع"]'),
    ('Step Pyramid of Djoser (Saqqara)', '["Djoser Pyramid","Zoser Pyramid","Step Pyramid of Zoser","هرم زوسر"]'),
    ('Great Sphinx of Giza', '["Sphinx of Giza","Great Sphinx","Abu al-Hol","أبو الهول"]'),
    ('Bent Pyramid (Dahshur)', '["Bent Pyramid","Southern Shining Pyramid","الهرم المنحني"]'),
    ('Red Pyramid (Dahshur)', '["Red Pyramid","North Pyramid","الهرم الأحمر"]'),
    ('Karnak Temple Complex (Luxor)', '["Karnak","Ipet-isut","Ipet-Isut","معبد الكرنك"]'),
    ('Luxor Temple', '["Ipet-resyt","Ipet Resyt","معبد الأقصر"]'),
    ('Mount Sinai (Jabal Musa)', '["Jabal Musa","Mount Moses","Gebel Musa","جبل موسى","جبل سيناء"]'),
    ('Saladin Citadel of Cairo', '["Cairo Citadel","Citadel of Saladin","قلعة صلاح الدين الأيوبي"]'),
    ('Edfu Temple of Horus', '["Edfu Temple","Temple of Horus at Edfu","معبد إدفو"]'),
    ('Kom Ombo Temple of Sobek and Horus', '["Kom Ombo Temple","Temple of Sobek and Haroeris","معبد كوم أمبو"]'),
    ('Citadel of Qaitbay (Alexandria)', '["Qaitbay Citadel","Fort of Qaitbay","قلعة قايتباي"]'),
    ('Abu Simbel Temples (Ramesses II & Nefertari)', '["Abu Simbel","Great Temple of Ramesses II","Temple of Nefertari","أبو سمبل"]'),
    ('Hawara Pyramid', '["Pyramid of Amenemhat III at Hawara","Hawara Pyramid of Amenemhat III","Hawara Labyrinth Site"]'),
    ('Pyramid of Senusret II at el-Lahun', '["Lahun Pyramid","El-Lahun Pyramid","Pyramid of Senusret II"]'),
    ('Gebel el-Silsila Quarry', '["Gebel el-Silsileh","Gebel el-Silsila Sandstone Quarries","Silsila Quarry"]'),
    ('Rosetta National Museum', '["Rashid National Museum","Rosetta Museum","متحف رشيد"]'),
    ('Abu Shahin Mill Rashid', '["Abu Shaheen Mill","Abu Shahin Windmill","Rosetta Windmill","طاحونة أبو شاهين"]'),
    ('Amasyali House Rashid', '["Amasyali House","Amasyali House Museum","Rosetta Historic House","منزل الأمصيلي"]'),
    ('Pharaohs Island Citadel', '["Pharaoh''s Island","Salah ad-Din Citadel on Pharaohs Island","Coral Island Citadel","جزيرة فرعون","قلعة صلاح الدين بجزيرة فرعون"]'),
    ('Athribis Archaeological Site, Sohag', '["Athribis Sohag","Athribis Temple","Wadi Hamama Archaeological Site","أثريبس"]'),
    ('Kom el-Dikka Archaeological Site, Alexandria', '["Kom el-Dikka","Kom el-Dikka Roman Theatre","Roman Amphitheatre of Alexandria","كوم الدكة"]'),
    ('Rommel Cave Museum, Matrouh', '["Rommel''s Cave Museum","Rommel Cave","Matrouh Rommel Museum","متحف كهف رومل"]'),
    ('Mons Claudianus Quarry', '["Mons Claudianus","Roman Mons Claudianus Quarry","Roman Imperial Porphyry Quarry"]'),
    ('Mons Porphyrites Quarry', '["Mons Porphyrites","Roman Porphyry Quarries","Porphyrites Mountain"]'),
    ('El Arish Castle', '["Arish Castle","El-Arish Fortress","Qal''at al-Arish","قلعة العريش"]'),
    ('Malkata Palace Site, Luxor', '["Malkata","Malqata Palace","Amenhotep III Palace City","ملقطة"]'),
    ('Deir el-Shelwit Temple, Luxor', '["Deir el-Shelwit","Temple of Isis at Deir el-Shelwit","Deir el-Shelwit Isis Temple","دير الشلويط"]'),
    ('Medamud Temple, Luxor', '["Medamud","Temple of Montu at Medamud","Madu","معبد المدامود"]'),
    ('Tod Temple, Luxor Governorate', '["Tod","Tôd Temple","Temple of Montu at Tod","معبد الطود"]'),
    ('Precinct of Mut, Karnak', '["Mut Temple Precinct","Temple of Mut at Karnak","Isheru of Mut","معبد موت"]'),
    ('Kiosk of Qertassi', '["Qertassi Kiosk","Kiosk of Qirtas","Trajan''s Kiosk at Qertassi","كشك قرطاسي"]'),
    ('Temple of Kalabsha, Aswan', '["Kalabsha Temple","Temple of Mandulis at Kalabsha","Talmis Temple","معبد كلابشة"]'),
    ('Monastery of Saint Macarius, Wadi el-Natrun', '["دير أبو مقار"]'),
    ('Monastery of Saint Bishoy, Wadi el-Natrun', '["دير الأنبا بيشوي"]')
) AS v("name", "alternate_names")
WHERE lower(p."name") = lower(v."name");

UPDATE "egypt_pois" AS p
SET "description" = v."description",
    "history_notes" = v."history_notes"
FROM (
  VALUES
    ('Great Pyramid of Giza (Khufu)', 'The largest pyramid on the Giza Plateau and the only surviving monument of the Seven Wonders of the Ancient World. The pyramid was built from millions of stone blocks and originally had a smooth limestone casing.', 'Built as the tomb of the Fourth Dynasty king Khufu around the 26th century BCE, the monument was the tallest human-made structure for millennia.'),
    ('Great Sphinx of Giza', 'A monumental limestone sculpture with a human head and lion body, set on the Giza Plateau near the pyramids.', 'The Sphinx is generally associated with the reign of Khafre in the Fourth Dynasty, although its precise construction history remains a subject of archaeological study.'),
    ('Karnak Temple Complex (Luxor)', 'A vast temple complex at ancient Thebes, with monumental gateways, courts, obelisks, and the Great Hypostyle Hall.', 'Karnak was expanded by successive rulers over more than a thousand years and served as a major center of the cult of Amun.'),
    ('Luxor Temple', 'A temple on the east bank of the Nile in Luxor, notable for its colonnades, statues, and long ceremonial connection to Karnak.', 'The temple was built and expanded primarily during the New Kingdom, especially under Amenhotep III and Ramesses II.'),
    ('Edfu Temple of Horus', 'One of Egypt’s best-preserved ancient temples, dedicated to the falcon god Horus and located in the Upper Egyptian town of Edfu.', 'The surviving temple was built during the Ptolemaic period, with construction beginning under Ptolemy III in 237 BCE and continuing for nearly two centuries.'),
    ('Kom Ombo Temple of Sobek and Horus', 'A distinctive double temple overlooking the Nile at Kom Ombo, dedicated to Sobek and the falcon-headed Haroeris (Horus the Elder).', 'The temple was built mainly during the Ptolemaic period and includes reliefs documenting religious practice and medical instruments.'),
    ('Dendera Temple Complex (Temple of Hathor)', 'A temple complex at Dendera dedicated chiefly to Hathor, known for its well-preserved halls, astronomical ceiling, and roof chapels.', 'Much of the standing temple dates to the Ptolemaic and Roman periods, although the site’s religious history is older.'),
    ('Abydos Temple of Seti I', 'A memorial temple at Abydos with finely carved reliefs and the celebrated King List in its Gallery of Ancestors.', 'Seti I began the temple during the Nineteenth Dynasty; his son Ramesses II completed it. Abydos was an important center of the cult of Osiris.'),
    ('Abu Simbel Temples (Ramesses II & Nefertari)', 'Two rock-cut temples in southern Egypt: the Great Temple of Ramesses II and the smaller temple dedicated to Queen Nefertari and Hathor.', 'The temples were carved during the reign of Ramesses II in the thirteenth century BCE and relocated in the 1960s to protect them from the rising waters of Lake Nasser.'),
    ('Philae Temple Complex (Agilkia Island Aswan)', 'A temple complex dedicated to Isis, relocated to Agilkia Island near Aswan after construction of the Aswan High Dam threatened the original island.', 'The monuments were dismantled and reconstructed in the 1970s as part of the international campaign to save Nubian monuments.'),
    ('Mount Sinai (Jabal Musa)', 'A mountain in the southern Sinai range, visited by pilgrims and hikers and traditionally associated with the biblical account of Moses.', 'The mountain forms part of the cultural landscape around Saint Catherine’s Monastery, a long-standing Christian pilgrimage destination.'),
    ('Siwa Oasis Shali Fortress', 'The historic core of Siwa town, built from kershef, a local mixture of salt-rich earth and palm wood.', 'Shali developed as a fortified settlement in the medieval period and remained the center of Siwa until parts of the structure were damaged by heavy rains in the twentieth century.'),
    ('White Monastery Sohag', 'A Coptic monastery near Sohag, named for its pale limestone church and known for its monumental basilica.', 'The monastery is associated with Saint Shenoute, whose leadership made it an influential center of Coptic monastic life in the fourth and fifth centuries.'),
    ('Red Monastery Sohag', 'A Coptic monastery near Sohag whose church preserves richly decorated architectural surfaces and paintings.', 'The monastery’s church dates to late antiquity and is an important surviving example of early Christian architecture in Upper Egypt.')
) AS v("name", "description", "history_notes")
WHERE lower(p."name") = lower(v."name")
  AND p."description" ILIKE '%place to explore in Egypt%';
